## Why This Is Asked
This question tests the ability to combine shortest-path computation, path counting, and path reconstruction into a cohesive solution. It also evaluates handling of multiple equal-cost routes and lexicographic tie-breaking.

## Key Concepts
- Dijkstra's algorithm for O(m log n) shortest paths
- Shortest-path DAG construction
- Topological ordering by distance values
- DP for counting distinct shortest paths
- Lexicographic path reconstruction

## Code Example
```javascript
function shortestStats(n, edges, s, t) {
  const adj = Array.from({ length: n }, () => []);
  for (const [u, v, w] of edges) {
    adj[u].push([v, w]);
  }

  const dist = new Array(n).fill(Infinity);
  const pq = [[0, s]];
  dist[s] = 0;

  while (pq.length) {
    const [d, u] = pq.pop();
    if (d > dist[u]) continue;
    for (const [v, w] of adj[u]) {
      if (dist[u] + w < dist[v]) {
        dist[v] = dist[u] + w;
        pq.push([dist[v], v]);
      }
    }
  }

  const dag = Array.from({ length: n }, () => []);
  for (let u = 0; u < n; u++) {
    for (const [v, w] of adj[u]) {
      if (dist[u] + w === dist[v]) {
        dag[u].push(v);
      }
    }
  }

  const ways = new Array(n).fill(0);
  ways[s] = 1;
  const order = Array.from({ length: n }, (_, i) => i)
    .sort((a, b) => dist[a] - dist[b]);

  for (const u of order) {
    for (const v of dag[u]) {
      ways[v] = (ways[v] + ways[u]) % 1000000007;
    }
  }

  const path = [];
  let curr = t;
  while (curr !== null) {
    path.unshift(curr);
    const preds = dag
      .map((list, u) => list.includes(curr) ? u : -1)
      .filter(u => u >= 0 && dist[curr] === dist[u] + 
        adj[u].find(([v]) => v === curr)?.[1]);
    preds.sort((a, b) => a - b);
    curr = preds.length > 0 ? preds[0] : null;
    if (curr === s) {
      path.unshift(s);
      break;
    }
  }

  return { distance: dist[t], ways: ways[t], path };
}
```

## Complexity Analysis
- Dijkstra: O(m log n)
- DAG construction: O(m)
- DP counting: O(m)
- Path reconstruction: O(n + m)
- Overall: O(m log n)

## Why This Is Asked
Tests DP understanding with obstacles and modular arithmetic; ensures edge-case handling and ability to implement both bottom-up and top-down approaches.

## Key Concepts
- DP with blockers (Fibonacci variant)
- Bottom-up vs top-down memoization
- Space optimization (O(1) possible with two variables)
- Modulo handling with BigInt or large integers

## Edge Cases
- **Start blocked (step 0)**: Return 0 immediately — no valid paths exist
- **End blocked (step N)**: dp[N] remains 0 since we cannot land on N
- **Consecutive blocked steps**: Creates a barrier; all steps after a chain of 2+ blocked steps will have dp[i]=0 (cannot be reached)

## Code Example
```javascript
const MOD = 1000000007n;

// Bottom-up DP: O(N) time, O(N) space
function countWaysBottomUp(blocked, n) {
  if (blocked[0]) return 0; // start blocked

  const dp = new Array(n + 1).fill(0n);
  dp[0] = 1n;

  for (let i = 1; i <= n; i++) {
    if (blocked[i]) {
      dp[i] = 0n; // blocked step: no ways to land here
      continue;
    }
    dp[i] = (dp[i-1] + (i >= 2 ? dp[i-2] : 0n)) % MOD;
  }
  return Number(dp[n]);
}

// Top-down memoization: O(N) time, O(N) space
function countWaysTopDown(blocked, n) {
  if (blocked[0]) return 0; // start blocked

  const memo = new Array(n + 1).fill(-1n);

  function solve(i) {
    if (i < 0) return 0n;    if (i === 0) return 1n;
    if (blocked[i]) return 0n; // this step is blocked
    if (memo[i] !== -1n) return memo[i];

    memo[i] = (solve(i-1) + solve(i-2)) % MOD;
    return memo[i];
  }

  return Number(solve(n));
}

// Space-optimized: O(N) time, O(1) space
function countWaysOptimized(blocked, n) {
  if (blocked[0]) return 0;

  let prev2 = 1n, prev1 = blocked[1] ? 0n : 1n;

  for (let i = 2; i <= n; i++) {
    const curr = blocked[i] ? 0n : (prev1 + prev2) % MOD;
    prev2 = prev1;
    prev1 = curr;
  }

  return Number(n === 0 ? prev2 : prev1);
}
```

## Complexity Analysis
- **Time**: O(N) for all variants — each step computed once
- **Space**: O(N) for basic DP/memoization, O(1) for optimized version
- **Modulo**: Applied at each addition to prevent overflow

## Why This Is Asked

Tests multi-state DP design to enforce a direction-run constraint with obstacles, requiring careful state construction and both memoized and tabular implementations.

## Key Concepts

- DP with extra dimensions for last direction and run-length
- Top-down memoization and bottom-up tabulation
- Modulo arithmetic and handling blocked cells; boundary cases when L is large or grid small

## Code Example

```javascript
function countPaths(grid, L){
  const n = grid.length, m = grid[0].length, MOD = 1000000007;
  if(grid[0][0] || grid[n-1][m-1]) return 0;
  const memo = Array.from({length:n},()=>Array.from({length:m},()=>Array.from({length:2},()=>Array(L+1).fill(-1))));
  const endI=n-1, endJ=m-1;
  function dfs(i,j,dir,run){
    if(i===endI && j===endJ) return 1;
    const val = memo[i][j][dir][run];
    if(val!==-1) return val;
    let res = 0;
    // right
    if(j+1<m){
      if((dir===0 && run<L) || dir===1){
        res = (res + dfs(i, j+1, 0, dir===0 ? run+1 : 1)) % MOD;
      }
    }
    // down
    if(i+1<n){
      if((dir===1 && run<L) || dir===0){
        res = (res + dfs(i+1, j, 1, dir===1 ? run+1 : 1)) % MOD;
      }
    }
    memo[i][j][dir][run] = res;
    return res;
  }
  let ans = (dfs(0,0,0,1) + dfs(0,0,1,1)) % MOD;
  return ans;
}
```

